<?php
require __DIR__.'/ui.php';auth();$p=db();$rows=$p->query("SELECT o.*,c.name customer,u.name seller FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.seller_id ORDER BY o.id DESC")->fetchAll();page_head('Pedidos');?>
<div class="card"><div class="actions"><?php if(can(['admin','gerente','vendedor','caixa'])):?><a class="btn primary" href="pdv.php">+ Novo pedido</a><?php endif;?></div><div class="table"><table><tr><th>Pedido</th><th>Cliente</th><th>Vendedor</th><th>Total</th><th>Entrega</th><th>Produção</th><th>Arte</th><th>Status</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['number'])?></td><td><?=e($x['customer']?:'Consumidor')?></td><td><?=e($x['seller']?:'-')?></td><td><?=money($x['total'])?></td><td><?=e($x['delivery_date'])?> <?=e($x['delivery_time'])?></td><td><?=e($x['production_stage'])?></td><td><?=e($x['art_status'])?></td><td><span class="badge <?=badge_class($x['status'])?>"><?=e($x['status'])?></span></td><td><a class="btn" href="order.php?id=<?=$x['id']?>">Abrir</a></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>